#include <iostream>

int value() { return 1; }                 // global

namespace outer
{
    int value() { return 2; }

    namespace inner
    {
        int value() { return 3; }

        int from_inner() { return value(); }
    }

    int from_outer() { return value(); }
}

int main()
{
    std::cout << value() << '\n';
    std::cout << ::value() << '\n';
    std::cout << outer::value() << '\n';
    std::cout << outer::inner::from_inner() << '\n';

    return 0;
}
